const crypto = require('crypto');

const inputData = $input.first().json;
const headers = inputData.headers || {};

// Secreto compartido para contingencia (definido para TSK-BE-22)
// Mínimo 32 caracteres
const secret = "akros_super_secret_contingency_key_32chars_min";

// Header enviado por TSK-BE-22: "sha256=<hex>"
const receivedSignature = headers['x-sportcomplex-signature'] || headers['X-SportComplex-Signature'] || '';

// 1. Obtener el cuerpo crudo exacto.
// Con la opción Raw Body, el Webhook guarda los bytes originales como binario en la propiedad 'data'.
let rawPayload = '';
let parsedPayload = null;

let rawFromBinary = null;
try {
  if ($input.first().binary && $input.first().binary.data) {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
    rawFromBinary = buf.toString('utf8');
  }
} catch (e) {
  rawFromBinary = null;
}

if (rawFromBinary) {
  rawPayload = rawFromBinary;
  try {
    parsedPayload = JSON.parse(rawFromBinary);
  } catch (e) {
    parsedPayload = inputData.body;
  }
} else if (inputData.rawBody) {
  rawPayload = inputData.rawBody;
  try {
    parsedPayload = JSON.parse(inputData.rawBody);
  } catch (e) {
    parsedPayload = inputData.body;
  }
} else {
  // Fallback si no viene rawBody
  rawPayload = typeof inputData.body === 'string' ? inputData.body : JSON.stringify(inputData.body);
  parsedPayload = typeof inputData.body === 'string' ? JSON.parse(inputData.body) : inputData.body;
}

// 2. Calcular HMAC-SHA256
const hmac = crypto.createHmac('sha256', secret);
hmac.update(rawPayload);
const calculatedSignature = `sha256=${hmac.digest('hex')}`;

// 3. Comparación segura
let isValid = false;
const receivedBuf = Buffer.from(String(receivedSignature));
const calculatedBuf = Buffer.from(calculatedSignature);
if (receivedBuf.length === calculatedBuf.length) {
  isValid = crypto.timingSafeEqual(receivedBuf, calculatedBuf);
}

return [
  {
    json: {
      isValid,
      payload: parsedPayload
    }
  }
];

// MODO PRUEBA: Resend solo permite enviar a tu propio correo hasta verificar el dominio.
// Cambia a false cuando akros.lat esté verificado en resend.com/domains.
const TEST_MODE = false;
const TEST_RECIPIENT = "jebolivar33@gmail.com";
const TEST_FROM = "onboarding@resend.dev";
const PROD_FROM = "Akros Alertas <no-reply@akros.lat>";

const rawPayload = $input.first().json.payload || {};

const motivo = rawPayload.motivo || "Mantenimiento imprevisto o eventualidad de fuerza mayor";
const servicioNombre = rawPayload.servicioNombre || `Servicio #${rawPayload.serviceId}`;
const afectados = (rawPayload.afectados || rawPayload.reservasAfectadas || [])
  .filter(c => c && (c.emailUsuario || c.email));

// Si no hay afectados en la lista, terminamos la ejecución
if (!afectados.length) {
  return [];
}

return afectados.map(cliente => {
  const nombre = cliente.nombreUsuario || cliente.nombre || "Usuario";
  const email = cliente.emailUsuario || cliente.email;
  const codigoReserva = cliente.codigoReserva || cliente.reservaId || "N/A";
  const fecha = cliente.fecha || "Próximas horas";
  const horario = cliente.horario || cliente.hora || "Horario programado";

  const html = `
  <!DOCTYPE html>
  <html lang="es">
  <head>
    <meta charset="utf-8">
    <style>
      body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background-color: #0b0f0d; margin: 0; padding: 24px; color: #f1f5f9; }
      .container { max-width: 580px; margin: 0 auto; background: #111815; border: 1px solid #1f2c25; border-radius: 14px; padding: 28px; }
      .badge-alert { display: inline-block; background: rgba(239, 68, 68, 0.15); color: #f87171; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; padding: 5px 12px; border-radius: 9999px; margin-bottom: 12px; }
      h1 { font-size: 20px; color: #ffffff; margin: 0 0 10px 0; }
      p { font-size: 14px; color: #94a3b8; line-height: 1.6; margin: 0 0 16px 0; }
      .detail-box { background: #16221d; border: 1px solid #23342c; border-radius: 10px; padding: 16px; margin: 20px 0; }
      .detail-item { font-size: 13px; color: #cbd5e1; margin-bottom: 8px; }
      .detail-item strong { color: #ffffff; }
      .notice-box { background: rgba(245, 158, 11, 0.1); border-left: 3px solid #f59e0b; padding: 12px; border-radius: 4px; font-size: 12px; color: #fbbf24; margin: 20px 0; line-height: 1.5; }
      .footer { font-size: 11px; color: #556b61; text-align: center; border-top: 1px solid #1f2c25; padding-top: 16px; margin-top: 24px; }
    </style>
  </head>
  <body>
    <div class="container">
      <div class="badge-alert">Aviso de Contingencia</div>
      <h1>Cancelación de Turno por Fuerza Mayor</h1>
      <p>Hola <strong>${nombre}</strong>,</p>
      <p>Te informamos que debido a una novedad operativa imprevista (<strong>${motivo}</strong>), el servicio <strong>${servicioNombre}</strong> ha sido inhabilitado temporalmente y tu reserva ha sido cancelada.</p>

      <div class="detail-box">
        <div class="detail-item"><strong>Código de Reserva:</strong> ${codigoReserva}</div>
        <div class="detail-item"><strong>Fecha:</strong> ${fecha}</div>
        <div class="detail-item"><strong>Horario:</strong> ${horario}</div>
        <div class="detail-item"><strong>Estado:</strong> Cancelada Administrativamente</div>
      </div>

      <div class="notice-box">
        <strong>Política de Reembolso y Reprogramación:</strong><br>
        Por políticas operativas, el sistema no realiza devoluciones bancarias automáticas. Tu pago se encuentra seguro y registrado a tu favor. Puedes solicitar la reprogramación de tu turno o coordinar tu saldo a favor directamente en la administración de AKROS Club.
      </div>

      <div class="footer">
        AKROS Club &bull; Notificación Oficial de Contingencia
      </div>
    </div>
  </body>
  </html>
  `;

return {
    json: {
      resendPayload: {
        from: TEST_MODE ? TEST_FROM : PROD_FROM,
        to: [TEST_MODE ? TEST_RECIPIENT : email],
        subject: `${TEST_MODE ? '[PRUEBA para ' + email + '] ' : ''}⚠️ Aviso Importante: Cancelación por Contingencia - Reserva ${codigoReserva}`,
        html: html
      }
    }
  };
});
